mapper.select:
/* ConsolMapper.selectMasterOrderList : Consol MasterOrder List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT A.* , COUNT(A.MBL_NO) OVER() AS SUM_COUNT , SUM(A.HBL_CNT) OVER() AS SUM_HBLNO , SUM(A.HBL_PIECES) OVER() AS SUM_PIECES , SUM(A.HBL_GWT) OVER() AS SUM_GWT , SUM(A.HBL_CBM) OVER() AS SUM_CBM , (SELECT obl.OBL_JOB_NO FROM TB_COM_OD cod INNER JOIN TB_COM_OBL obl ON obl.OBL_JOB_NO = cod.OBL_JOB_NO WHERE cod.OD_JOB_NO = A.OD_JOB_NO) AS OBL_JOB_NO FROM ( SELECT MAX(mod.FINISH_YN) AS FINISH_YN ,MAX(mod.OB_DATE) AS OB_DATE ,MAX(mod.AR_DATE) AS AR_DATE ,MAX(mod.CUST_CODE_LV1) AS CUST_CODE_LV1 ,MAX(mod.LINE_CODE) AS LINE_CODE ,MAX(mod.LINE_NAME) AS LINE_NAME ,MAX(mod.VOYAGE) AS VOYAGE ,MAX(mod.VESSEL_FLIGHT) AS VESSEL_FLIGHT ,MAX(mod.ORIG_CODE) AS ORIG_CODE ,MAX(mod.ORIG_COUNTRY) AS ORIG_COUNTRY ,MAX(mod.DEST_COUNTRY) AS DEST_COUNTRY ,MAX(mod.DEST_CODE) AS DEST_CODE ,MAX(mod.DEST_PORT) AS DEST_PORT ,MAX(mod.MBL_NO) AS MBL_NO ,MAX(mod.CUSTOMS_CODE) AS CUSTOMS_CODE ,MAX(mod.CUSTOMS_DPT_CODE) AS CUSTOMS_DPT_CODE ,MAX(mod.ASSIGNMENT_WH_CODE) AS ASSIGNMENT_WH_CODE ,MAX(mod.DISC_WH_CODE) AS DISC_WH_CODE ,COUNT(od.OD_JOB_NO) AS HBL_CNT ,SUM(od.PIECES) AS HBL_PIECES ,SUM(od.GWT) AS HBL_GWT ,SUM(od.CBM) AS HBL_CBM ,COUNT(CASE od.CD_TYPE WHEN 'Y' THEN 1 END) AS CD_TYPE1_CNT ,COUNT(CASE od.CD_TYPE WHEN 'N' THEN 1 END) AS CD_TYPE2_CNT ,COUNT(CASE od.CD_TYPE WHEN 'B' THEN 1 END) AS CD_TYPE3_CNT ,COUNT(CASE od.CD_TYPE WHEN 'E' THEN 1 END) AS CD_TYPE4_CNT ,mod.OD_JOB_NO ,MAX(mod.BOUND) AS BOUND ,MAX(mod.BOUND_TYPE) AS BOUND_TYPE ,MAX(mod.OB_TIME) AS OB_TIME ,MAX(mod.AR_TIME) AS AR_TIME ,(SELECT CUSTOMER_NAME_ENG FROM TB_SMS_CUSTOMER WHERE ENT_CODE = MAX(mod.ENT_CODE) AND CUSTOMER_CODE = MAX(mod.CUST_CODE_LV1)) AS CUST_NAME_LV1 ,(SELECT CASE ISNULL(MF_USER_ID, '') WHEN '' THEN 'N' ELSE 'Y' END FROM TB_ECM_OD_ADDITIONAL WHERE OD_JOB_NO = mod.OD_JOB_NO) AS SEND_MANIFEST_YN ,COUNT(CASE WHEN ISNULL(od.ECM_YN,'') = 'Y' THEN 1 END) AS ECM_Y_CNT ,COUNT(CASE WHEN (ISNULL(od.ECM_YN,'') = '' OR od.ECM_YN = 'N') AND od.BL_TYPE_MH IS NOT NULL THEN 1 END) AS ECM_N_CNT
,MAX(CASE WHEN ISNULL(ad.SIMPLE_EDI_STATUS, '') NOT IN ('', 'ERROR') THEN 'Y' END) AS SEND_SIMPLE_DOC_YN
,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = MAX(mod.ENT_CODE) AND CODE = MAX(mod.ORIG_CODE) AND GROUP_CODE = 'CITY_PORT') AS ORIG_NAME ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = MAX(mod.ENT_CODE) AND CODE = MAX(mod.DEST_CODE) AND GROUP_CODE = 'CITY_PORT') AS DEST_NAME
FROM TB_ECM_OD mod LEFT JOIN TB_ECM_OD od ON od.MASTER_OD_JOB_NO = mod.OD_JOB_NO AND od.BL_TYPE_MH = 'H' LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
AND mod.BL_TYPE_MH = 'M' AND mod.HBL_NO IS NULL GROUP BY mod.OD_JOB_NO
)A

/* ConsolMapper.selectHouseOrderList : Consol HouseOrder List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT A.* ,COUNT(A.OD_JOB_NO) OVER() AS SUM_COUNT ,SUM(ISNULL(A.PIECES,0)) OVER() AS SUM_PIECES ,SUM(ISNULL(A.GWT,0)) OVER() AS SUM_GWT ,SUM(ISNULL(A.CBM,0)) OVER() AS SUM_CBM FROM( SELECT od.CONSOL_YN ,od.CUST_CODE_LV1 ,od.CUST_CODE_LV2 ,od.PO_DATE ,od.PO_NO ,od.HBL_NO ,od.MBL_NO ,od.MASTER_OD_JOB_NO ,od.SHIPPER_NAME ,od.CONSIGNEE_NAME ,od.CONSIGNEE_NAME_LOC ,od.PIECES ,od.GWT ,od.AMOUNT_LOC ,od.AMOUNT_CUR ,od.COMMODITY_ITEM ,od.CD_TYPE ,od.CD_USE_TYPE ,od.ECM_TYPE ,od.OB_DATE ,od.AR_DATE ,od.BOUND ,od.BOUND_TYPE ,od.OD_JOB_NO ,od.ENT_BUSINESS_CODE ,od.CBM ,od.CUSTOMS_ID_TYPE ,od.ECM_BUY_TYPE ,od.AGENT_REG_NO ,od.AGENT_NAME ,od.SELLER_REG_NO ,od.SELLER_NAME ,od.SALES_BROKER_REG_NO ,od.SALES_BROKER_NAME ,od.ECM_YN ,STUFF((SELECT ',' + PO_NO FROM TB_ECM_OD_PO_INFO WHERE OD_JOB_NO = od.OD_JOB_NO FOR XML PATH('')) ,1 ,1, '') AS PO_NO_LIST ,od.REGISTER_USER_ID AS REGISTER_USER_NAME
,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) AS CONSIGNEE_HP ,dbo.Cryptography(od.OD_JOB_NO, od.CUSTOMS_ID_ENC, 1) AS CUSTOMS_ID
,od.CONSIGNEE_HP ,od.CUSTOMS_ID
FROM TB_ECM_OD od
WITH (INDEX(TB_ECM_OD_X01))
INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE od.BL_TYPE_MH = 'H'
AND od.MASTER_OD_JOB_NO = #{srchMasterOdJobNo}
AND od.CUST_CODE_LV1 = #{srchEcmCustomerCode}
AND od.CONSOL_YN = 'N' AND ad.LAST_POD_STATUS >= 'ECM010' AND ad.LAST_POD_STATUS != 'ECM040'
AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP' AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'
AND od.PO_DATE >= CONVERT(DATE, #{srchHouseStartDate}, ${srchDateFormat}) AND od.PO_DATE <= CONVERT(DATE, #{srchHouseEndDate}, ${srchDateFormat})
AND 1 = 0
AND (SELECT USER_LOGIN_ID FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = od.REGISTER_USER_ID) LIKE CONCAT('%',#{srchHouseRegistUser},'%')
AND od.CUST_CODE_LV${level} = #{srchEcmCustomerCode}
AND ${srchCusType} = #{srchCuslv1}
AND ${srchCusType} = #{srchCuslv2}
AND ${srchNoTypeHouse} IN (#{item})
AND ${srchNoTypeHouse} LIKE CONCAT('%',#{srchNoHouse},'%')
) A

/* ConsolMapper.selectImpMasterList : Consol 수입 Master List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT mod.OD_JOB_NO ,ad.SIMPLE_DOC_NO ,MAX(mod.MBL_NO) AS MBL_NO ,MAX(mod.AR_DATE) AS AR_DATE ,MAX(mod.ORIG_CODE) AS ORIG_CODE ,MAX(mod.BOUND) AS BOUND ,MAX(mod.BOUND_TYPE) AS BOUND_TYPE ,MAX(mod.DEST_PORT) AS DEST_PORT FROM TB_ECM_OD mod LEFT JOIN TB_ECM_OD od ON od.MASTER_OD_JOB_NO = mod.OD_JOB_NO AND od.BL_TYPE_MH = 'H' LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE mod.BOUND = #{srchBound} AND mod.BOUND_TYPE = 'IMP' AND mod.BL_TYPE_MH = 'M' AND mod.HBL_NO IS NULL AND mod.AR_DATE >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND mod.AR_DATE <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')
GROUP BY mod.OD_JOB_NO, ad.SIMPLE_DOC_NO

/* ConsolMapper.selectImpHouseList : Consol 수입 House List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO ,od.HBL_NO ,od.ALLOWED_ITEM_CODE ,od.COMMODITY_ITEM FROM TB_ECM_OD od WHERE od.BOUND = #{srchBound} AND od.BOUND_TYPE = 'IMP' AND od.BL_TYPE_MH = 'H' AND od.MASTER_OD_JOB_NO IS NULL AND od.PO_DATE >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND od.PO_DATE <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')

/* ConsolMapper.selectImpHouseConsolList : Consol 수입 House 콘솔건 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO ,od.HBL_NO ,od.BOUND ,od.BOUND_TYPE FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
AND ad.SIMPLE_DOC_NO = #{srchSimpleDocNo}
AND ad.SIMPLE_DOC_NO IS NULL
WHERE od.MASTER_OD_JOB_NO = #{srchMasterOdJobNo} AND od.BL_TYPE_MH = 'H'

/* ConsolMapper.selectExpMasterList : Consol 수출 Master List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT mod.OD_JOB_NO ,MAX(mod.MBL_NO) AS MBL_NO ,MAX(mod.OB_DATE) AS OB_DATE ,MAX(mod.VESSEL_FLIGHT) AS VESSEL_FLIGHT ,MAX(mod.ORIG_CODE) AS ORIG_CODE ,MAX(mod.DEST_CODE) AS DEST_CODE ,MAX(mod.BOUND) AS BOUND ,MAX(mod.BOUND_TYPE) AS BOUND_TYPE ,(SELECT COUNT(OD_JOB_NO) FROM TB_ECM_OD WHERE MASTER_OD_JOB_NO = mod.OD_JOB_NO AND BL_TYPE_MH = 'H') AS HBL_CNT FROM TB_ECM_OD mod WHERE mod.BOUND = #{srchBound} AND mod.BOUND_TYPE = 'EXP' AND mod.BL_TYPE_MH = 'M' AND mod.HBL_NO IS NULL AND mod.OB_DATE >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND mod.OB_DATE <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')
GROUP BY mod.OD_JOB_NO

/* ConsolMapper.selectExpHouseList : Consol 수출 House List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO ,od.HBL_NO ,od.SHIPPER_NAME ,CONCAT(ISNULL(od.SHIPPER_ADDRESS, ''), ISNULL(od.SHIPPER_ADDRESS_A, ''), ISNULL(od.SHIPPER_ADDRESS_B, ''), ISNULL(od.SHIPPER_ADDRESS_C, ''), ISNULL(od.SHIPPER_ADDRESS_D, '')) AS SHIPPER_ADDRESS ,od.CONSIGNEE_NAME ,CONCAT(ISNULL(od.CONSIGNEE_ADDRESS, ''), ISNULL(od.CONSIGNEE_ADDRESS_A, ''), ISNULL(od.CONSIGNEE_ADDRESS_B, ''), ISNULL(od.CONSIGNEE_ADDRESS_C, ''), ISNULL(od.CONSIGNEE_ADDRESS_D, '')) AS CONSIGNEE_ADDRESS ,od.COMMODITY_ITEM FROM TB_ECM_OD od WHERE od.BOUND = #{srchBound} AND od.BOUND_TYPE = 'EXP' AND od.BL_TYPE_MH = 'H' AND od.MASTER_OD_JOB_NO IS NULL AND od.PO_DATE >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND od.PO_DATE <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')

/* ConsolMapper.selectExpHouseConsolList : Consol 수출 House 콘솔건 List */
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

SELECT
	 od.OD_JOB_NO
	,od.HBL_NO
	,od.BOUND
	,od.BOUND_TYPE
FROM TB_ECM_OD od
WHERE od.MASTER_OD_JOB_NO = #{srchMasterOdJobNo}
AND od.BL_TYPE_MH = 'H'

/* ConsolMapper.selectMinSimpleDocNo : 전송되지 않은 건 중 가장 오래된 제출번호 조회 */ SELECT TOP 1 ad.SIMPLE_DOC_NO AS MIN_SIMPLE_DOC_NO ,CASE WHEN ad.SIMPLE_DOC_NO IS NULL THEN 3 WHEN od.BL_TYPE_MH = 'H' THEN 1 ELSE 2 END AS ORDER_BY_SEQ FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo} AND ( (od.BL_TYPE_MH = 'H' AND CASE WHEN od.DOCUMENT_YN = 'Y' THEN 'Y' ELSE 'N' END = #{documentYn} AND ISNULL(ad.SIMPLE_EDI_STATUS, '') IN ('', 'ERROR') AND ISNULL(ad.SIMPLE_ERROR_SEND_YN, '') != 'Y')
OR od.BL_TYPE_MH = 'M'
) ORDER BY ORDER_BY_SEQ, ad.SIMPLE_DOC_NO

