/* ConsolMapper.insertMasterOrder : 마스터오더 insert */
	INSERT INTO TB_ECM_OD(
		   OD_JOB_NO
		  ,ENT_CODE
		  ,ENT_BUSINESS_CODE
		  ,SOLUTION
		  ,BOUND
		  ,BOUND_TYPE
		  ,PO_DATE
		  ,BL_TYPE_MH
		  ,CONSOL_YN
		  ,MBL_NO
		  ,VOYAGE
		  ,LINE_CODE
		  ,LINE_NAME
		  ,MASTER_OD_JOB_NO
		  ,CUST_CODE_LV1
		  ,CUST_CODE_LV2
		  ,CUST_CODE_LV3
		  ,CUST_CODE_LV4
		  ,CUST_CODE_LV5
		  ,CUST_CODE_LV6
		  ,CUST_CODE_LV7
		  ,VESSEL_FLIGHT
		  ,ORIG_CODE
		  ,ORIG_NAME
		  ,ORIG_COUNTRY
		  ,DEST_COUNTRY
		  ,OB_DATE
		  ,OB_TIME
		  ,DEST_CODE
		  ,DEST_NAME
		  ,AR_DATE
		  ,AR_TIME
		  ,CUSTOMS_CODE
		  ,CUSTOMS_DPT_CODE
		  ,ASSIGNMENT_WH_CODE
		  ,DISC_WH_CODE
		  ,VENDER_ID_1

		  ,DEST_PORT

		  ,INPUT_METHOD


		  		,CUST_LV1_REMARK


		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)VALUES(
		   #{odJobNo}
		  ,#{entCode}
		  ,#{entBusinessCode}
		  ,#{solution}
		  ,#{bound}
		  ,#{boundType}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,'M'
		  ,#{consolYn}
		  ,LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
		  ,#{voyage}
		  ,#{lineCode}
		  ,#{lineName}
		  ,#{odJobNo}
		  ,#{custCodeLv1}
		  ,#{custCodeLv2}
		  ,#{custCodeLv3}
		  ,#{custCodeLv4}
		  ,#{custCodeLv5}
		  ,#{custCodeLv6}
		  ,#{custCodeLv7}
		  ,#{vesselFlight}
		  ,#{origCode}
		  ,#{origName}
		  ,#{origCountry}
		  ,#{destCountry}
		  ,CONVERT(DATE, #{obDate}, ${dateFormat})
		  ,#{obTime}
		  ,#{destCode}
		  ,#{destName}
		  ,CONVERT(DATE, #{arDate}, ${dateFormat})
		  ,#{arTime}
		  ,#{customsCode}
		  ,#{customsDptCode}
		  ,#{assignmentWhCode}
		  ,#{discWhCode}
		  ,#{venderId1}

		  ,#{destPort}

		  ,'WEB'


		  		,#{custLv1Remark}


		  ,#{registerUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	);
	INSERT INTO TB_ECM_OD_ADDITIONAL(
		   OD_JOB_NO
		  ,SIMPLE_DOC_NO
		  ,EDI_MAILBOX_SEQ_NO
		  ,MASTER_OD_JOB_NO
		  ,MBL_NO
		  ,BL_TYPE_MH

		  ,CARRYOUT_CODE

	)VALUES(
		   #{odJobNo}
		  ,#{simpleDocNo}
		  ,#{ediMailboxSeqNo}
		  ,#{odJobNo}
		  ,LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
		  ,'M'

		  ,#{carryoutCode}

	);

mapper.select:
/* ConsolMapper.selectConsolTarget : 콘솔대상 조회 */ SELECT od.HBL_NO ,od.CURRENCY_CODE ,od.AMOUNT_CUR ,od.OD_JOB_NO ,'N' AS NEW_CONSOL_YN ,od.CD_TYPE ,od.BOUND ,od.BOUND_TYPE ,od.ORIG_CODE ,od.CUSTOMS_CODE ,od.CUSTOMS_DPT_CODE ,od.AMOUNT_LOC ,od.AMOUNT_USD ,od.EXCHANGE_RATE ,CASE WHEN od.DOCUMENT_YN = 'Y' THEN 'Y' ELSE 'N' END AS DOCUMENT_YN ,ad.SIMPLE_DOC_NO ,ad.CARRYOUT_CODE ,od.ASSIGNMENT_WH_CODE ,ad.EMS_APPROVAL_NO ,od.DEST_COUNTRY AS DEST_COUNTRH_H ,od.SHIPPER_COUNTRY_CODE ,od.CONSIGNEE_COUNTRY_CODE FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
WHERE od.MASTER_OD_JOB_NO IN(#{item})
WHERE od.MASTER_OD_JOB_NO = #{odJobNo}
AND od.BL_TYPE_MH = 'H'

mapper.update:
/* ConsolMapper.updateComObl : 콘솔수정시 TB_COM_OBL 수정 */
	UPDATE TB_COM_OBL SET
		   MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))

		  ,LINE_CODE = #{lineCode}
		  ,LINE_NAME = #{lineName}

		  ,ORIG_CODE = #{origCode}
		  ,ORIG_NAME = #{origName}
		  ,OB_DATE = CONVERT(DATE, #{obDate},  ${dateFormat})
		  ,OB_TIME = #{obTime}
		  ,DEST_CODE = #{destCode}
		  ,DEST_NAME = #{destName}
		  ,AR_DATE = CONVERT(DATE, #{arDate},  ${dateFormat})
		  ,AR_TIME = #{arTime}
		  ,ISSUE_DATE = CONVERT(DATE, #{obDate},  ${dateFormat})
		  ,ISSUING_CARRIERS = #{issuingCarriers}


		  ,VESSEL_FLIGHT = #{vesselFlight}
		  ,VESSEL_VOYAGE = #{voyage}


		  ,VIA_BY_A = #{vesselFlight}
		  ,VESSEL_FLIGHT = #{vesselFlight}
		  ,FWRD_CODE = #{fwrdCode}
		  ,FWRD_NAME = #{fwrdName}
		  ,FWRD_ADDRESS = SUBSTRING(ISNULL(CAST(UPPER(#{fwrdAddress}) AS NVARCHAR(300)), ''), 1, 60)
		  ,FWRD_ADDRESS_A = SUBSTRING(ISNULL(CAST(UPPER(#{fwrdAddress}) AS NVARCHAR(300)), ''), 61, 60)
		  ,FWRD_ADDRESS_B = SUBSTRING(ISNULL(CAST(UPPER(#{fwrdAddress}) AS NVARCHAR(300)), ''), 121, 60)
		  ,FWRD_ADDRESS_C = SUBSTRING(ISNULL(CAST(UPPER(#{fwrdAddress}) AS NVARCHAR(300)), ''), 181, 60)
		  ,FWRD_ADDRESS_D = SUBSTRING(ISNULL(CAST(UPPER(#{fwrdAddress}) AS NVARCHAR(300)), ''), 241, 60)
		  ,SIGN_ACTING_AS = #{signActingAs}

		  ,SIGN_HIS_AGENT = #{signHisAgent}


			  ,ISSUE_PLACE_CODE = #{origCode}



		  ,UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE OBL_JOB_NO = #{oblJobNo}

/* ConsolMapper.updateComOrder : 콘솔수정시 TB_COM_OD 수정 */
	UPDATE TB_COM_OD SET
		   MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))


		  ,OBAR_DATE = CONVERT(DATE, #{obDate},  ${dateFormat})
		  ,ORIG_DEST_CODE = #{destCode}


		  ,OBAR_DATE = CONVERT(DATE, #{arDate},  ${dateFormat})
		  ,ORIG_DEST_CODE = #{origCode}


		  ,UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE OD_JOB_NO = #{odJobNo}

/* ConsolMapper.updateComOrderBus : 콘솔수정시 TB_COM_OD_BUS 수정 */
	UPDATE TB_COM_OD_BUS SET
		   MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))


		  ,PORT_CODE = #{destCode}


		  ,PORT_CODE = #{origCode}


	WHERE OD_JOB_NO = #{odJobNo}

/* ConsolMapper.updateConsolOrder : 오더 콘솔 */
	UPDATE TB_ECM_OD SET
		   MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
		  ,MASTER_OD_JOB_NO = #{odJobNo}
		  ,LINE_CODE = #{lineCode}
		  ,LINE_NAME = #{lineName}
		  ,VOYAGE = #{voyage}
		  ,VESSEL_FLIGHT = #{vesselFlight}
		  ,ORIG_CODE = #{origCode}
		  ,ORIG_NAME = #{origName}
		  ,OB_DATE = #{obDate}
		  ,OB_TIME = #{obTime}
		  ,DEST_CODE = #{destCode}
		  ,DEST_NAME = #{destName}
		  ,AR_DATE = #{arDate}
		  ,AR_TIME = #{arTime}
		  ,DEST_COUNTRY = #{destCountry}
		  ,SHIPPER_COUNTRY_CODE = #{origCountry}
		  ,CONSIGNEE_COUNTRY_CODE = #{destCountry}

		  ,CONSOL_YN = 'Y'

		  ,CUSTOMS_CODE = #{customsCode}
		  ,CUSTOMS_DPT_CODE = #{customsDptCode}

		  ,ASSIGNMENT_WH_CODE = #{assignmentWhCode}
		  ,ORIG_COUNTRY = #{origCountry}

		  ,DISC_WH_CODE = #{discWhCode}

		  ,DEST_PORT = #{destPort}

		  ,UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE OD_JOB_NO = #{odJobNo};
	UPDATE TB_ECM_OD_ADDITIONAL SET
		   EDI_MAILBOX_SEQ_NO = #{ediMailboxSeqNo}
		  ,MASTER_OD_JOB_NO = #{odJobNo}
		  ,MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))


		  ,SIMPLE_DOC_NO = NULL


		  ,SIMPLE_DOC_NO = #{simpleDocNo}


	WHERE OD_JOB_NO = #{odJobNo};
	UPDATE TB_ECM_POD SET
		   BL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
	WHERE OD_JOB_NO = #{odJobNo};
	UPDATE TB_ECM_POD_01 SET
		   BL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
	WHERE OD_JOB_NO = #{odJobNo};

/* ConsolMapper.updateConsolOrderBatch : 오더 콘솔 */
	UPDATE TB_ECM_OD SET
		   MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
		  ,MASTER_OD_JOB_NO = #{masterOdJobNo}
		  ,LINE_CODE = #{lineCode}
		  ,LINE_NAME = #{lineName}
		  ,VOYAGE = #{voyage}
		  ,VESSEL_FLIGHT = #{vesselFlight}
		  ,OB_DATE = #{obDate}
		  ,OB_TIME = #{obTime}
		  ,DEST_CODE = #{destCode}
		  ,DEST_NAME = #{destName}
		  ,AR_DATE = #{arDate}
		  ,AR_TIME = #{arTime}


				,DEST_COUNTRY = #{destCountry}
				,SHIPPER_COUNTRY_CODE = #{origCountry}
			    ,CONSIGNEE_COUNTRY_CODE = #{destCountry}			  	





							,SHIPPER_COUNTRY_CODE = #{origCountry}


							,CONSIGNEE_COUNTRY_CODE = #{destCountry}


							,DEST_COUNTRY = #{destCountry}



		  				,DEST_COUNTRY = #{destCountry}
						,SHIPPER_COUNTRY_CODE = #{origCountry}
					    ,CONSIGNEE_COUNTRY_CODE = #{destCountry}	




		  ,CONSOL_YN = 'Y'
		  ,AMOUNT_LOC = #{amountLoc}
		  ,AMOUNT_USD = #{amountUsd}
		  ,EXCHANGE_RATE = #{exchangeRate}

		  ,ORIG_COUNTRY = #{origCountry}

			  ,ASSIGNMENT_WH_CODE = #{assignmentWhCode}


		  ,DISC_WH_CODE = #{discWhCode}

		  ,DEST_PORT = #{destPort}
		  ,CUSTOMS_CODE = #{customsCode}
		  ,CUSTOMS_DPT_CODE = #{customsDptCode}
		  ,ORIG_CODE = #{origCode}
		  ,ORIG_NAME = #{origName}



		  		,ORIG_CODE = #{origCode}




		  	,SHIPPER_FAX = #{shipperFax}
