/* ConsolMapper.updateSimpleDocNoImp : 수입마감 통관목록제출번호 업데이트 */
	UPDATE ad SET ad.SIMPLE_DOC_NO = #{simpleDocNo}
	FROM TB_ECM_OD od
		 INNER JOIN TB_ECM_OD_ADDITIONAL ad
		 			ON ad.OD_JOB_NO = od.OD_JOB_NO
	WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}


	AND (CASE WHEN od.DOCUMENT_YN = 'Y' THEN 'Y' ELSE 'N' END = #{documentYn} OR od.BL_TYPE_MH = 'M')


	AND od.BL_TYPE_MH = 'H'
	AND CASE WHEN od.DOCUMENT_YN = 'Y' THEN 'Y' ELSE 'N' END = #{documentYn}




			AND od.ECM_YN = 'Y'

/* ConsolMapper.updateSimpleDocNoExp : 수출마감 통관목록제출번호 업데이트 */

	UPDATE TB_ECM_OD_ADDITIONAL SET SIMPLE_DOC_NO = @RES_STOCK_NO
	WHERE OD_JOB_NO = #{odJobNo}

/* ConsolMapper.updateSimpleDocNo : 통관목록제출번호 업데이트 */
	UPDATE TB_ECM_OD_ADDITIONAL SET
