/* ConsolMapper.selectCloseOrderList : 마감대상오더조회 */ SELECT od.OD_JOB_NO ,CASE od.BL_TYPE_MH WHEN 'M' THEN od.MBL_NO ELSE od.HBL_NO END AS BL_NO ,od.BL_TYPE_MH ,od.CD_TYPE ,od.BOUND ,od.BOUND_TYPE ,od.MBL_NO ,od.HBL_NO ,CASE WHEN od.DOCUMENT_YN = 'Y' THEN 'Y' ELSE 'N' END AS DOCUMENT_YN
,CASE WHEN ISNULL(od.ORIG_CODE, '') = '' THEN 'Y' END AS UPDATE_ORIG_CODE_YN ,CASE WHEN ISNULL(od.CUSTOMS_CODE, '') = '' AND ISNULL(od.CUSTOMS_DPT_CODE, '') = '' THEN 'Y' END AS UPDATE_CUSTOMS_CODE_YN ,mod.ORIG_CODE AS ORIG_CODE_M ,mod.CUSTOMS_CODE AS CUSTOMS_CODE_M ,mod.CUSTOMS_DPT_CODE AS CUSTOMS_DPT_CODE_M
FROM TB_ECM_OD od
INNER JOIN TB_ECM_OD mod ON mod.OD_JOB_NO = od.MASTER_OD_JOB_NO
WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}

