mapper.update:
/* ConsolMapper.updateHsnMax : 오더 마감시 MAX(HSN)+1 업데이트 */
	UPDATE TB_ECM_OD SET
		   HSN = (SELECT CONCAT(REPLICATE('0', 4 - LEN(MAX(ISNULL(HSN, 0)) + 1 )), MAX(ISNULL(HSN, 0)) + 1) FROM TB_ECM_OD WHERE MASTER_OD_JOB_NO = #{MASTER_OD_JOB_NO} AND BL_TYPE_MH = 'H')
	WHERE OD_JOB_NO = #{OD_JOB_NO};

	UPDATE TB_ECM_OD_ADDITIONAL SET
		   HSN = (SELECT HSN FROM TB_ECM_OD WHERE OD_JOB_NO = #{OD_JOB_NO})
	WHERE OD_JOB_NO = #{OD_JOB_NO};

/* ConsolMapper.updateHsnOrderClose : 오더 마감시 HSN 업데이트 */
	UPDATE od SET
		   od.HSN = CONCAT(REPLICATE('0', 4 - LEN(od.rowNum)), od.rowNum)
	FROM (
		SELECT HSN, ROW_NUMBER() OVER (ORDER BY HBL_NO) AS rowNum
		FROM TB_ECM_OD
		WHERE MASTER_OD_JOB_NO = #{masterOdJobNo}
		AND BL_TYPE_MH = 'H'
	) od;

	UPDATE ad SET
		   ad.HSN = od.HSN
	FROM TB_ECM_OD_ADDITIONAL ad
		 INNER JOIN TB_ECM_OD od
		 			ON od.OD_JOB_NO = ad.OD_JOB_NO
	WHERE ad.MASTER_OD_JOB_NO = #{masterOdJobNo};

