/* ConsolMapper.updateDeconsolAll : 삭제마스터오더에 콘솔되어있던 하우스 콘솔해제 */ UPDATE TB_ECM_OD SET CONSOL_YN = 'N' ,MBL_NO = NULL ,MASTER_OD_JOB_NO = NULL ,LINE_CODE = NULL ,VESSEL_FLIGHT = NULL ,OB_DATE = NULL ,OB_TIME = NULL ,DEST_CODE = NULL ,DEST_NAME = NULL ,AR_DATE = NULL ,AR_TIME = NULL
,ORIG_COUNTRY = NULL
,DEST_COUNTRY = NULL
,MRN = NULL ,MSN = NULL
,DEST_PORT = NULL ,ORIG_CODE = NULL ,ORIG_NAME = NULL ,CUSTOMS_CODE = NULL ,CUSTOMS_DPT_CODE = NULL ,ASSIGNMENT_WH_CODE = NULL
,UPDATE_USER_ID = #{updateUserId} ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE()) WHERE MASTER_OD_JOB_NO IN(#{item}) AND BL_TYPE_MH = 'H'; UPDATE TB_ECM_OD_ADDITIONAL SET MASTER_OD_JOB_NO = NULL ,MBL_NO = NULL WHERE MASTER_OD_JOB_NO IN(#{item}) AND BL_TYPE_MH = 'H';

/* ConsolMapper.updateDeconsolExrate : 삭제마스터오더에 콘솔되어있던 하우스 환율처리 */
	UPDATE TB_ECM_OD SET
		   AMOUNT_LOC = #{AMOUNT_LOC}
