		  ,EXCHANGE_RATE = #{EXCHANGE_RATE}
	WHERE OD_JOB_NO = #{OD_JOB_NO}

mapper.select:
/* ConsolMapper.selectHblValidate : hbl유효성체크 */ WITH TMP AS( SELECT A.ENT_CODE, A.HBL_NO FROM (
SELECT #{item} AS HBL_NO ,#{entCode} AS ENT_CODE
) A LEFT JOIN TB_ECM_OD OD ON OD.ENT_CODE = #{entCode} AND A.HBL_NO = OD.HBL_NO WHERE OD.OD_JOB_NO IS NULL ) SELECT COUNT(TMP.HBL_NO) AS NOT_BL_CNT , STUFF((SELECT ',' + HBL_NO FROM TMP WHERE ENT_CODE = t.ENT_CODE FOR XML PATH('')), 1, 1, '') FROM TMP t GROUP BY t.ENT_CODE

SELECT A.* ,COUNT(A.HBL_NO) OVER() AS SUM_COUNT ,SUM(ISNULL(A.PIECES,0)) OVER() AS SUM_PIECES ,SUM(ISNULL(A.AMOUNT_LOC,0)) OVER() AS SUM_AMOUNT ,SUM(ISNULL(A.GWT,0)) OVER() AS SUM_GWT ,SUM(ISNULL(A.CBM,0)) OVER() AS SUM_CBM FROM( SELECT mod.MBL_NO , od.HBL_NO , od.SHIPPER_NAME , od.CONSIGNEE_NAME , CONCAT(ISNULL(od.SHIPPER_ADDRESS, ''), ISNULL(od.SHIPPER_ADDRESS_A, ''), ISNULL(od.SHIPPER_ADDRESS_B, ''), ISNULL(od.SHIPPER_ADDRESS_C, ''), ISNULL(od.SHIPPER_ADDRESS_D, '')) AS SHIPPER_ADDRESS , CONCAT(ISNULL(od.CONSIGNEE_ADDRESS, ''), ISNULL(od.CONSIGNEE_ADDRESS_A, ''), ISNULL(od.CONSIGNEE_ADDRESS_B, ''), ISNULL(od.CONSIGNEE_ADDRESS_C, ''), ISNULL(od.CONSIGNEE_ADDRESS_D, '')) AS CONSIGNEE_ADDRESS , od.PIECES , od.AMOUNT_USD AS AMOUNT_LOC , od.GWT , od.CBM , od.COMMODITY_ITEM , 'NDR' AS CD_TYPE , CONCAT(CONVERT(VARCHAR,mod.OB_DATE,23),' ', mod.OB_TIME) AS OB_DATE , CONCAT(CONVERT(VARCHAR,mod.AR_DATE,23),' ', mod.AR_TIME) AS AR_DATE , od.SHIPPER_COUNTRY_CODE , ISNULL(mod.VESSEL_FLIGHT,'') AS VESSEL_FLIGHT , ISNULL(mod.VOYAGE,'') AS VOYAGE , (SELECT TOP 1 USER_NAME_ENG FROM TB_SMS_USER WHERE ENT_CODE = #{srchEntCode} AND USER_ID = #{userId}) AS USER_NAME , (SELECT TOP 1 CUSTOMER_NAME_ENG FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{srchEntCode} AND CUSTOMER_CODE =#{srchEcmCustomerCode}) AS CUSTOMER_NAME , (SELECT TOP 1 USER_TEL FROM TB_SMS_USER WHERE ENT_CODE = #{srchEntCode} AND USER_ID = #{userId}) AS USER_TEL , (SELECT TOP 1 USER_FAX FROM TB_SMS_USER WHERE ENT_CODE = #{srchEntCode} AND USER_ID = #{userId}) AS USER_FAX , (SELECT NAME_ENG FROM TB_SMS_CODE_DETAIL Code WHERE Code.GROUP_CODE = 'CITY_PORT' AND Code.CODE = mod.ORIG_CODE) ORIG_NAME , (SELECT NAME_ENG FROM TB_SMS_CODE_DETAIL Code WHERE Code.GROUP_CODE = 'CITY_PORT' AND Code.CODE =mod.DEST_CODE) DEST_NAME , CASE WHEN ISNULL(C.CONTAINER_LIST,'') != '' THEN LEFT(C.CONTAINER_LIST,LEN(C.CONTAINER_LIST)-1) ELSE '' END AS CONTAINER_INFO FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD mod ON od.MASTER_OD_JOB_NO = mod.OD_JOB_NO AND mod.BL_TYPE_MH = 'M' LEFT JOIN ( SELECT AA.OD_JOB_NO, BB.HBL_NO, AA.CBM ,(SELECT CASE ISNULL(A.CNTR_NO,'') WHEN '' THEN '' ELSE ISNULL(A.CNTR_NO,'')+CHAR(10) END + CASE ISNULL(A.CNTR_CODE,'') WHEN '' THEN '' ELSE '('+ISNULL(A.CNTR_CODE,'')+')'+CHAR(10) END + CASE ISNULL(A.CNTR_SEAL_NO_1,'') WHEN '' THEN '' ELSE ISNULL(A.CNTR_SEAL_NO_1,'')+CHAR(10)END + CASE ISNULL(A.CNTR_SEAL_NO_2,'') WHEN '' THEN '' ELSE ISNULL(A.CNTR_SEAL_NO_2,'')+CHAR(10)END + CASE ISNULL(A.CNTR_SEAL_NO_3,'') WHEN '' THEN '' ELSE ISNULL(A.CNTR_SEAL_NO_3,'')+CHAR(10)END FROM TB_ECM_OD_CONTAINER A WHERE A.OD_JOB_NO = AA.OD_JOB_NO FOR XML PATH('') )AS CONTAINER_LIST FROM TB_ECM_OD_CONTAINER AA, TB_ECM_OD BB WHERE BB.MASTER_OD_JOB_NO = #{srchMasterOdJobNo} AND AA.OD_JOB_NO = BB.OD_JOB_NO GROUP BY AA.OD_JOB_NO,BB.HBL_NO,AA.CBM ) C ON od.OD_JOB_NO = c.OD_JOB_NO WHERE od.BL_TYPE_MH = 'H' AND od.CONSOL_YN = 'Y' AND od.MASTER_OD_JOB_NO = #{srchMasterOdJobNo}
AND od.CUST_CODE_LV1 = #{srchEcmCustomerCode}
AND mod.BOUND = 'AIR' AND mod.BOUND_TYPE = 'EXP'
AND mod.BOUND = 'AIR' AND mod.BOUND_TYPE = 'IMP'
AND mod.BOUND = 'SEA' AND mod.BOUND_TYPE = 'EXP'
AND mod.BOUND = 'SEA' AND mod.BOUND_TYPE = 'IMP'
)A

